package com.example.governance.dictionary;

import java.sql.Types;
import java.util.*;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class DictionaryStore {
    public record Directory(long id, Long parentId, String name, int sortOrder) {}
    public record Entry(long id, long directoryId, String code, String name, String meaning, String dataType, Integer length, Integer precision, String description) {}
    public record Input(Long directoryId, String code, String name, String meaning, String dataType, Integer length, Integer precision, String description) {}
    public record Page(List<Entry> rows, long total) {}
    private static final Set<String> TYPES = Set.of("varchar", "char", "integer", "bigint", "decimal", "double", "date", "datetime", "boolean");
    private final JdbcTemplate jdbc;
    public DictionaryStore(JdbcTemplate jdbc) { this.jdbc = jdbc; }
    public List<Directory> directories() { return jdbc.query("SELECT id,parent_id,name,sort_order FROM dictionary_directories ORDER BY sort_order,id", (r,n) -> new Directory(r.getLong(1),r.getObject(2,Long.class),r.getString(3),r.getInt(4))); }
    public List<Entry> entries() { return jdbc.query("SELECT id,directory_id,code,name,meaning,data_type,field_length,field_precision,description FROM dictionary_entries ORDER BY id DESC", (r,n) -> new Entry(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getObject(7,Integer.class),r.getObject(8,Integer.class),r.getString(9))); }
    public Page page(Long directoryId, String search, int page, int size) {
        if(page<1||size<1||size>100||page>100000)throw new IllegalArgumentException("分页参数无效");
        String q=search==null?"":search.trim(); if(q.length()>200)throw new IllegalArgumentException("查询条件过长");
        List<Object> args=new ArrayList<>(); StringBuilder where=new StringBuilder(" WHERE 1=1");
        if(directoryId!=null){Set<Long> ids=new HashSet<>();ids.add(directoryId);boolean changed=true;List<Directory> all=directories();if(all.stream().noneMatch(d->d.id()==directoryId))throw new IllegalArgumentException("目录不存在");while(changed){changed=false;for(var d:all)if(d.parentId()!=null&&ids.contains(d.parentId())&&ids.add(d.id()))changed=true;}where.append(" AND directory_id IN (").append(String.join(",",Collections.nCopies(ids.size(),"?"))).append(")");args.addAll(ids);}
        if(!q.isEmpty()){String pattern="%"+q.toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%";where.append(" AND (LOWER(code) LIKE ? ESCAPE '!' OR LOWER(name) LIKE ? ESCAPE '!' OR LOWER(meaning) LIKE ? ESCAPE '!')");args.add(pattern);args.add(pattern);args.add(pattern);}
        long total=Objects.requireNonNull(jdbc.queryForObject("SELECT COUNT(*) FROM dictionary_entries"+where,Long.class,args.toArray()));
        List<Object> pageArgs=new ArrayList<>(args);pageArgs.add(size);pageArgs.add((page-1)*size);
        List<Entry> rows=jdbc.query("SELECT id,directory_id,code,name,meaning,data_type,field_length,field_precision,description FROM dictionary_entries"+where+" ORDER BY id DESC LIMIT ? OFFSET ?",(r,n)->new Entry(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getObject(7,Integer.class),r.getObject(8,Integer.class),r.getString(9)),pageArgs.toArray());return new Page(rows,total);
    }
    private void lockDirectories(){jdbc.queryForList("SELECT setting_key FROM platform_settings WHERE setting_key='internal.organization.lock' FOR UPDATE");}
    private String clean(String value, int max, String label) { String s=value==null?"":value.trim(); if(s.isEmpty()||s.length()>max) throw new IllegalArgumentException(label+"无效"); return s; }
    @Transactional public long createDirectory(String name, Long parent) { name=clean(name,120,"目录名称");if(name.contains("/"))throw new IllegalArgumentException("目录名称不能包含 /");lockDirectories(); if(parent!=null && jdbc.queryForList("SELECT id FROM dictionary_directories WHERE id=? FOR UPDATE",Long.class,parent).isEmpty()) throw new IllegalArgumentException("父目录不存在"); checkName(name,parent,null); final String n=name; var key=new GeneratedKeyHolder(); jdbc.update(c->{var s=c.prepareStatement("INSERT INTO dictionary_directories(parent_id,name) VALUES (?,?)",new String[]{"id"}); if(parent==null)s.setNull(1,Types.BIGINT);else s.setLong(1,parent);s.setString(2,n);return s;},key);return Objects.requireNonNull(key.getKey()).longValue(); }
    private void checkName(String name, Long parent, Long id) { if(directories().stream().anyMatch(d->Objects.equals(parent,d.parentId()) && name.equals(d.name()) && !Objects.equals(id,d.id()))) throw new IllegalArgumentException("同级目录名称已存在"); }
    @Transactional public void renameDirectory(long id,String name) { name=clean(name,120,"目录名称");if(name.contains("/"))throw new IllegalArgumentException("目录名称不能包含 /");lockDirectories(); Directory d=directories().stream().filter(x->x.id()==id).findFirst().orElseThrow(()->new IllegalArgumentException("目录不存在")); checkName(name,d.parentId(),id);jdbc.update("UPDATE dictionary_directories SET name=? WHERE id=?",name,id); }
    @Transactional public void deleteDirectory(long id) { lockDirectories();if(jdbc.queryForList("SELECT id FROM dictionary_directories WHERE id=? FOR UPDATE",Long.class,id).isEmpty())throw new IllegalArgumentException("目录不存在"); if(jdbc.queryForObject("SELECT COUNT(*) FROM dictionary_directories WHERE parent_id=?",Integer.class,id)>0 || jdbc.queryForObject("SELECT COUNT(*) FROM dictionary_entries WHERE directory_id=?",Integer.class,id)>0)throw new IllegalArgumentException("目录包含子目录或字典，不能删除");jdbc.update("DELETE FROM dictionary_directories WHERE id=?",id); }
    public Input validate(Input input) { if(input==null||input.directoryId()==null)throw new IllegalArgumentException("请选择目录"); String code=clean(input.code(),100,"字典标识"), name=clean(input.name(),200,"字典名"), meaning=clean(input.meaning(),200,"字典含义"), type=clean(input.dataType(),20,"类型").toLowerCase(Locale.ROOT); if(!code.matches("[A-Za-z_][A-Za-z0-9_]*"))throw new IllegalArgumentException("字典标识格式无效");if(!TYPES.contains(type))throw new IllegalArgumentException("字典类型无效");if(input.length()!=null&&input.length()<1)throw new IllegalArgumentException("长度必须为正整数");if(input.precision()!=null&&(!Set.of("decimal","double").contains(type)||input.precision()<0||input.length()==null||input.precision()>input.length()))throw new IllegalArgumentException("精度无效");String description=input.description()==null?"":input.description().trim();if(description.length()>1000)throw new IllegalArgumentException("描述过长");return new Input(input.directoryId(),code,name,meaning,type,input.length(),input.precision(),description); }
    @Transactional public long create(Input raw) { Input v=validate(raw); if(jdbc.queryForList("SELECT id FROM dictionary_directories WHERE id=? FOR UPDATE",Long.class,v.directoryId()).isEmpty())throw new IllegalArgumentException("目录不存在"); var key=new GeneratedKeyHolder();try {jdbc.update(c->{var s=c.prepareStatement("INSERT INTO dictionary_entries(directory_id,code,name,meaning,data_type,field_length,field_precision,description) VALUES (?,?,?,?,?,?,?,?)",new String[]{"id"});s.setLong(1,v.directoryId());s.setString(2,v.code());s.setString(3,v.name());s.setString(4,v.meaning());s.setString(5,v.dataType());s.setObject(6,v.length());s.setObject(7,v.precision());s.setString(8,v.description());return s;},key);}catch(DataIntegrityViolationException ex){throw new IllegalArgumentException("字典标识已存在");}return Objects.requireNonNull(key.getKey()).longValue(); }
    @Transactional public void update(long id,Input raw) { Input v=validate(raw); Entry existing=entries().stream().filter(x->x.id()==id).findFirst().orElseThrow(()->new IllegalArgumentException("字典不存在"));if(!existing.code().equals(v.code()))throw new IllegalArgumentException("字典标识不能修改");if(jdbc.queryForList("SELECT id FROM dictionary_directories WHERE id=? FOR UPDATE",Long.class,v.directoryId()).isEmpty())throw new IllegalArgumentException("目录不存在");jdbc.update("UPDATE dictionary_entries SET directory_id=?,name=?,meaning=?,data_type=?,field_length=?,field_precision=?,description=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",v.directoryId(),v.name(),v.meaning(),v.dataType(),v.length(),v.precision(),v.description(),id); }
    public void delete(long id) { if(jdbc.update("DELETE FROM dictionary_entries WHERE id=?",id)!=1)throw new IllegalArgumentException("字典不存在"); }
    public Long directoryByPath(String path) { Long parent=null;for(String name:path.split("/",-1)){final Long p=parent;var found=directories().stream().filter(d->Objects.equals(d.parentId(),p)&&d.name().equals(name.trim())).findFirst();if(found.isEmpty())throw new IllegalArgumentException("目录路径不存在");parent=found.get().id();}return parent; }
}
